mapper.select:
SELECT template_id,tenant_id, link_id,alarm_flow_id,user_type,msg_notify_type,msg_notify_limit,
        msg_notify_company,leader_flag,sign_flag,rollback_flag,time_limit,notify_admin_flag,delete_flag,
        app_ver_code,industry_code,id as attr_id,msg_send_time_interval as msgSendTimeInterval,
real_link_type realLinkType,data_filter_permiss dataFilterPermiss,custom_admin customAdmin,time_start_alram timeStartAlram,
time_end_alram timeEndAlram,voice_alram voiceAlram, time_remind timeRemind,time_remind_auto timeRemindAuto,time_remind_number timeRemindNumber,
if_later_remind ifLaterRemind,later_remind_company laterRemindCompany,time_push_type timePushType,time_limit_push timeLimitPush,enable_acceptance_mode enableAcceptanceMode,time_limit_acceptance timeLimitAcceptance
FROM vm_flow_link_attr
WHERE  link_id = #{linkId} AND alarm_flow_id = #{alarmFlowId}

    AND template_id =  #{templateId}


    AND tenant_id =  #{tenantId}

SELECT template_id,tenant_id, link_id,alarm_flow_id,user_type,msg_notify_type,msg_notify_limit, msg_notify_company,leader_flag,sign_flag,rollback_flag,time_limit,notify_admin_flag,delete_flag, app_ver_code,industry_code,id as attr_id FROM vm_flow_link_attr
AND alarm_flow_id = #{alarmFlowId}
limit 1

select.if:
select config.link_id as linkId,config.role_id as userOrRoles from vm_flow_link_industry_config  config
where config.link_id=#{linkId}

    and app_ver_code is not null and industry_code is not null


    and app_ver_code =#{appVerCode}


    and industry_code=#{industryCode}

mapper.select:
select fll.template_id as alarm_flow_id,flic.link_id from vm_flow_link_industry_config flic INNER JOIN vm_flow_template_link as fll on flic.link_id = fll.cur_link INNER JOIN vm_flow_template as ft on ft.template_id = fll.template_id and flic.app_ver_code = ft.app_ver_code and flic.industry_code = ft.industry_code where flic.delete_flag = 0 and flic.app_ver_code =#{param.appVerCode} and flic.industry_code =#{param.industryCode}
and
FIND_IN_SET(#{item},flic.role_id)
GROUP BY fll.template_id,flic.link_id UNION all select fll.template_id as alarm_flow_id,flic.link_id from vm_flow_link_industry_config flic INNER JOIN vm_flow_template_link as fll on flic.link_id = fll.cur_link INNER JOIN vm_flow_template as ft on ft.template_id = fll.template_id and ft.app_ver_code is null and ft.industry_code is null where flic.delete_flag = 0 and flic.app_ver_code is null and flic.industry_code is null
and
FIND_IN_SET(#{item},flic.role_id)
GROUP BY fll.template_id,flic.link_id union all select attr.alarm_flow_id,r.link_id from vm_flow_link_role r LEFT JOIN vm_flow_link_attr attr on attr.id = r.attr_id where attr.tenant_id = #{param.tenantId} and attr.app_ver_code =#{param.appVerCode} and attr.industry_code =#{param.industryCode}
and r.role_id in
#{item}
GROUP BY attr.alarm_flow_id,r.link_id
